// ccc.hpp — shared contest harness generated by `ccc`. Safe to edit.
//
// A level's main.cpp only defines `Input`, `parse(Reader&)` and
// `solve(const Input&, std::ostream&)`, then calls `ccc::run_level`, which:
//   * finds every in_level-N_<id>.txt in the level directory,
//   * writes out/out_level-N_<id>.txt,
//   * diffs against out_level-N_<id>.txt when one ships with the level
//     (the example), exiting non-zero on any mismatch.
#pragma once

