#include <set>
#include <sstream>
#include <stack>
#include <stdexcept>
#include <string>
#include <string_view>
#include <tuple>
#include <type_traits>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>

#ifndef CCC_LEVEL_DIR
#define CCC_LEVEL_DIR "."
#endif

using i64 = long long;
using u64 = unsigned long long;
namespace fs = std::filesystem;

namespace ccc {

template <class T>
T convert(const std::string& s) {
    if constexpr (std::is_same_v<T, std::string>) {
        return s;
    } else {
        T v{};
        std::istringstream ss(s);
        if (!(ss >> v)) throw std::runtime_error("cannot parse token '" + s + "'");
        return v;
    }
}

// Split `s` on any character in `seps`, skipping empty fields:
//   split("3, 4,,foo")        -> {"3", "4", "foo"}
//   split("New York;5", ";")  -> {"New York", "5"}
inline constexpr std::string_view kSeps = " \t,;";

inline std::vector<std::string> split(std::string_view s, std::string_view seps = kSeps) {
    std::vector<std::string> out;
    std::size_t i = 0;
    while (i < s.size()) {
        const auto start = s.find_first_not_of(seps, i);
        if (start == std::string_view::npos) break;
        auto end = s.find_first_of(seps, start);
        if (end == std::string_view::npos) end = s.size();
        out.emplace_back(s.substr(start, end - start));
        i = end;
    }
    return out;
}

// A cursor over one record's fields: a stringstream that also splits on commas.
//   Fields f("3,4,foo");
//   i64 x, y; std::string name;
//   f >> x >> y >> name;                      // stream style
//   auto [a, b] = f.take<i64, double>();      // typed tuple
//   auto p = f.as<Point, i64, i64>();         // straight into a struct (aggregate or constructor)
//   auto ys = f.rest<i64>();                  // everything that's left
class Fields {
public:
    Fields() = default;
    explicit Fields(std::string_view text, std::string_view seps = kSeps) : items_(split(text, seps)) {}
    explicit Fields(std::vector<std::string> items) : items_(std::move(items)) {}

    template <class T = i64>
    T next() {
        if (pos_ >= items_.size())
            throw std::runtime_error("record has only " + std::to_string(items_.size()) + " fields");
        return convert<T>(items_[pos_++]);
    }

    template <class T>
    Fields& operator>>(T& out) {
        out = next<T>();
        return *this;
    }

    // Braced init guarantees left-to-right evaluation, so fields are read in order.
    template <class... Ts>
    std::tuple<Ts...> take() { return std::tuple<Ts...>{next<Ts>()...}; }

    template <class S, class... Ts>
    S as() { return std::make_from_tuple<S>(take<Ts...>()); }

    template <class T = i64>
    std::vector<T> rest() {
        std::vector<T> v;
        while (pos_ < items_.size()) v.push_back(convert<T>(items_[pos_++]));
        return v;
    }

    std::size_t size() const { return items_.size(); }
    std::size_t remaining() const { return items_.size() - pos_; }
    bool done() const { return pos_ >= items_.size(); }
    const std::string& operator[](std::size_t i) const { return items_.at(i); }

private:
    std::vector<std::string> items_;
    std::size_t pos_ = 0;
};

// Line-aware tokenizer over the whole input.
//   next<T>()               next token, crossing line breaks
//   values<T>(n)            next n tokens
//   line_values<T>()        rest of the current line, or the next non-empty line
//   raw_line()              next full line, untouched
//   eof()                   only whitespace left
//   r >> a >> b             stream style, crossing line breaks
//   take<Ts...>()           next tokens as a typed tuple, crossing line breaks
//   as<S, Ts...>()          next tokens straight into a struct, crossing line breaks
//   set_separators(" ,")    also split on commas (applies from the next line read)
//   fields(seps)            one line as a Fields record, split on `seps`
//   fields_lines(n, seps)   n lines joined into one record
//   record<S, Ts...>(seps)  one line straight into a struct
//   records<S, Ts...>(n)    n lines, one struct each
class Reader {
public:
    explicit Reader(std::istream& is) {
        std::string s;
        while (std::getline(is, s)) {
            if (!s.empty() && s.back() == '\r') s.pop_back();
            lines_.push_back(std::move(s));
        }
    }

    void set_separators(std::string_view seps) { seps_ = seps; }

    template <class T = i64>
    T next() { return convert<T>(token()); }

    template <class T>
    Reader& operator>>(T& out) {
        out = next<T>();
        return *this;
    }

    template <class... Ts>
    std::tuple<Ts...> take() { return std::tuple<Ts...>{next<Ts>()...}; }

    template <class S, class... Ts>
    S as() { return std::make_from_tuple<S>(take<Ts...>()); }

    template <class T = i64>
    std::vector<T> values(std::size_t n) {
        std::vector<T> v;
        v.reserve(n);
        for (std::size_t i = 0; i < n; ++i) v.push_back(next<T>());
        return v;
    }

    template <class T = i64>
    std::vector<T> line_values() {
        if (tok_ >= toks_.size() && !load_line()) throw std::runtime_error("unexpected end of input");
        std::vector<T> v;
        while (tok_ < toks_.size()) v.push_back(convert<T>(toks_[tok_++]));
        return v;
    }

    // The rest of the current line (if any tokens are left), otherwise the next
    // non-empty line, split on `seps`. To keep spaces inside fields (e.g.
    // fields(",") for "New York,5"), call it at the start of a line.
    Fields fields(std::string_view seps = kSeps) {
        if (tok_ < toks_.size()) {
            std::vector<std::string> items;
            for (; tok_ < toks_.size(); ++tok_)
                for (auto& f : split(toks_[tok_], seps)) items.push_back(std::move(f));
            return Fields(std::move(items));
        }
        return Fields(next_nonempty_line(), seps);
    }

    // A record spread over `n` lines, as one list of fields.
    Fields fields_lines(std::size_t n, std::string_view seps = kSeps) {
        std::vector<std::string> items;
        for (std::size_t i = 0; i < n; ++i)
            for (auto& f : split(next_nonempty_line(), seps)) items.push_back(std::move(f));
        return Fields(std::move(items));
    }

    template <class S, class... Ts>
    S record(std::string_view seps = kSeps) { return fields(seps).template as<S, Ts...>(); }

    template <class S, class... Ts>
    std::vector<S> records(std::size_t n, std::string_view seps = kSeps) {
        std::vector<S> v;
        v.reserve(n);
        for (std::size_t i = 0; i < n; ++i) v.push_back(record<S, Ts...>(seps));
        return v;
    }

    std::string raw_line() {
        toks_.clear();
        tok_ = 0;
        if (line_ >= lines_.size()) throw std::runtime_error("unexpected end of input");
        return lines_[line_++];
    }

    bool eof() const {
        if (tok_ < toks_.size()) return false;
        return std::all_of(lines_.begin() + static_cast<std::ptrdiff_t>(line_), lines_.end(),
                           [this](const std::string& l) { return split(l, seps_).empty(); });
    }

private:
    std::vector<std::string> lines_;
    std::size_t line_ = 0;
    std::vector<std::string> toks_;
    std::size_t tok_ = 0;
    std::string seps_ = " \t";

    bool load_line() {
        while (line_ < lines_.size()) {
            toks_ = split(lines_[line_++], seps_);
            tok_ = 0;
            if (!toks_.empty()) return true;
        }
        return false;
    }

    std::string next_nonempty_line() {
        toks_.clear();
        tok_ = 0;
        while (line_ < lines_.size()) {
            const auto& l = lines_[line_++];
            if (l.find_first_not_of(" \t") != std::string::npos) return l;
        }
        throw std::runtime_error("unexpected end of input");
    }

    std::string token() {
        if (tok_ >= toks_.size() && !load_line()) throw std::runtime_error("unexpected end of input");
        return toks_[tok_++];
    }
};

inline std::vector<std::string> normalized_lines(const std::string& text) {
    std::vector<std::string> out;
    std::istringstream ss(text);
    for (std::string l; std::getline(ss, l);) {
        while (!l.empty() && std::isspace(static_cast<unsigned char>(l.back()))) l.pop_back();
        out.push_back(l);
    }
    while (!out.empty() && out.back().empty()) out.pop_back();
    return out;
}

inline std::string slurp(const fs::path& p) {
    std::ifstream f(p, std::ios::binary);
    std::ostringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

// argv[1]: only run this input id (e.g. "0-example"); argv[2]: level dir override.
template <class Input, class Parse, class Solve>
int run_level(int level, int argc, char** argv, Parse parse, Solve solve) {
    const std::string only = argc > 1 ? argv[1] : "";
    const fs::path dir = argc > 2 ? fs::path(argv[2]) : fs::path(CCC_LEVEL_DIR);
    const std::string tag = "level-" + std::to_string(level) + "_";
    fs::create_directories(dir / "out");

    std::vector<fs::path> inputs;
    for (const auto& e : fs::directory_iterator(dir)) {
        const auto name = e.path().filename().string();
        if (e.is_regular_file() && name.rfind("in_" + tag, 0) == 0 && e.path().extension() == ".txt")
            inputs.push_back(e.path());
    }
    std::sort(inputs.begin(), inputs.end());
    if (inputs.empty()) {
        std::cerr << "no in_" << tag << "*.txt files in " << dir << "\n";
        return 2;
    }

    int failures = 0;
    for (const auto& path : inputs) {
        const auto stem = path.stem().string();
        const auto id = stem.substr(("in_" + tag).size());
        if (!only.empty() && id != only) continue;

        std::cout << "  " << std::left << std::setw(16) << id << std::flush;
        const auto t0 = std::chrono::steady_clock::now();
        std::string result;
        try {
            std::ifstream f(path);
            Reader r(f);
            Input in = parse(r);
            std::ostringstream out;
            solve(in, out);
            result = out.str();
        } catch (const std::exception& ex) {
            std::cout << "ERROR " << ex.what() << "\n";
            ++failures;
            continue;
        }
        const auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                            std::chrono::steady_clock::now() - t0).count();

        const fs::path out_path = dir / "out" / ("out_" + tag + id + ".txt");
        std::ofstream(out_path, std::ios::binary) << result;

        const fs::path expected_path = dir / ("out_" + tag + id + ".txt");
        if (!fs::exists(expected_path)) {
            std::cout << "wrote out/" << out_path.filename().string() << " (" << ms << " ms)\n";
            continue;
        }
        const auto got = normalized_lines(result);
        const auto want = normalized_lines(slurp(expected_path));
        if (got == want) {
            std::cout << "OK   matches expected (" << ms << " ms)\n";
            continue;
        }
        ++failures;
        std::size_t i = 0;
        while (i < got.size() && i < want.size() && got[i] == want[i]) ++i;
        std::cout << "FAIL line " << i + 1 << ": got '" << (i < got.size() ? got[i] : "<eof>")
                  << "' expected '" << (i < want.size() ? want[i] : "<eof>") << "'\n";
    }
    return failures == 0 ? 0 : 1;
}

}  // namespace ccc

